text:
{
 "title": "令和6年能登半島地震災害の被災者に係る所得税法等の臨時特例法",
 "lead": {
  "es": "令和《れいわ》6年《ねん》能登半島地震《のとはんとうじしん》の災害《さいがい》で被害《ひがい》を受《う》けた人《ひと》の負担《ふたん》を軽《かる》くするため、令和《れいわ》5年分《ねんぶん》の所得税《しょとくぜい》（もうけにかかる国《くに》の税金《ぜいきん》）について、特別《とくべつ》なしくみを決《き》めた法律《ほうりつ》です。",
  "hs": "令和6年能登半島地震《のとはんとうじしん》災害の被災者《ひさいしゃ》の負担を軽くするため、令和5年分の所得税（収入にかかる国の税金）について、災害による損失の特別な扱《あつか》いを決めた法律。",
  "std": "令和6年能登半島地震災害の被災者の負担を軽減するため、令和5年分の所得税について、災害による損失に係る特別な措置を講じる法律。",
  "univ": "令和6年能登半島地震災害（今般の災害）の被災者の負担の軽減を図るため、令和5年分の所得税について、今般の災害による損失に係る特別な措置を講ずる法律。"
 },
 "facts": [
  {
   "es": "この災害《さいがい》で家《いえ》や家財《かざい》（家《いえ》の中《なか》の家具《かぐ》など）に損《そん》が出《で》たとき、令和《れいわ》5年分《ねんぶん》の所得《しょとく》で、その損《そん》の金額《きんがく》を「雑損控除《ざっそんこうじょ》」（災害《さいがい》などの損《そん》を税金《ぜいきん》の計算《けいさん》から引《ひ》くしくみ）の対象《たいしょう》にできます。",
   "hs": "この災害で住宅や家財などに損失が出たとき、令和5年分の所得で、その損失の金額を雑損控除《ざっそんこうじょ》（災害などの損失を所得から差し引く仕組み）の対象にできる。",
   "std": "この災害で住宅や家財などの資産に損失が生じたときは、令和5年分の所得で、その損失の金額を雑損控除の対象にできる。",
   "univ": "雑損控除の特例：今般の災害により住宅や家財等の資産について損失が生じたときは、令和5年分の所得において、その損失の金額を雑損控除の適用対象とすることができる。"
  },
  {
   "es": "この災害《さいがい》で家《いえ》や家財《かざい》にとても大《おお》きな被害《ひがい》を受《う》けたときは、雑損控除《ざっそんこうじょ》のかわりに選《えら》んで、令和《れいわ》5年分《ねんぶん》の所得税《しょとくぜい》を「災害減免法《さいがいげんめんほう》」で軽《かる》くしたり、なくしたりしてもらえます。",
   "hs": "この災害で住宅や家財に甚大《じんだい》な被害《ひがい》を受けたときは、雑損控除《ざっそんこうじょ》とどちらかを選んで、令和5年分の所得税について、災害減免法《さいがいげんめんほう》による軽減や免除《めんじょ》を受けられる。",
   "std": "この災害で住宅や家財に甚大な被害を受けたときは、雑損控除との選択により、令和5年分の所得税について災害減免法による軽減・免除を受けられる。",
   "univ": "災害減免法の特例：今般の災害により住宅や家財について甚大な被害を受けたときは、雑損控除との選択により、令和5年分の所得税について、災害減免法による軽減免除の適用を受けることができる。"
  },
  {
   "es": "この災害《さいがい》で仕事《しごと》に使《つか》う物《もの》などに損《そん》が出《で》たとき、その損《そん》の金額《きんがく》を、令和《れいわ》5年分《ねんぶん》の仕事《しごと》のもうけを計算《けいさん》するときの「必要経費《ひつようけいひ》」（仕事《しごと》にかかったお金《かね》）に入《い》れられます。",
   "hs": "この災害で事業用の資産などに損失が出たとき、その損失の金額を、令和5年分の事業所得などを計算するときの必要経費《ひつようけいひ》（仕事にかかった費用）に入れられる。",
   "std": "この災害で事業用資産などに損失が生じたときは、その損失の金額を、令和5年分の事業所得などの計算で必要経費に算入できる。",
   "univ": "被災事業用資産等の損失の必要経費算入の特例：今般の災害により事業用資産等について損失が生じたときは、その損失の金額について、令和5年分の事業所得等の金額の計算上、必要経費に算入することができる。"
  },
  {
   "es": "この法律《ほうりつ》は、公布《こうふ》（みんなに知《し》らせること）の日《ひ》から使《つか》われ始《はじ》めます。",
   "hs": "この法律は、公布《こうふ》（国民に知らせること）の日から施行《しこう》される。",
   "std": "公布の日から施行する。",
   "univ": "施行期日：この法律は、公布の日から施行する。"
  }
 ]
}
